# Section 8 of the paper: run by paper_results.jl, which defines the helpers used here.

"The group generated by the matrices `generators`, as the closure of {unit} under left multiplication."
function s8_generate(generators, unit)
    group = Set([unit])
    frontier = [unit]
    while !isempty(frontier)
        frontier = unique([g * x for x in frontier for g in generators if !(g * x in group)])
        union!(group, frontier)
    end
    return group
end

"A permutation of 1:n, given by its images, in cycle notation."
function s8_cycles(w)
    seen, parts = falses(length(w)), String[]
    for i in eachindex(w)
        (seen[i] || w[i] == i) && continue
        cycle, j = Int[], i
        while !seen[j]
            seen[j] = true
            push!(cycle, j)
            j = w[j]
        end
        push!(parts, "(" * join(cycle, " ") * ")")
    end
    return isempty(parts) ? "id" : join(parts)
end

function section_8()
    # The weights of e1, ..., e7 in the basis ε1, ε2 of X^* (ε3 = -ε1 - ε2, ε_{i+3} = -ε_i, ε7 = 0).
    ε = [[1, 0], [0, 1], [-1, -1], [-1, 0], [0, -1], [1, 1], [0, 0]]
    weight(i, j) = ε[i] + ε[j]
    short_roots = ε[1:6]
    long_roots = [ε[2] - ε[3], ε[3] - ε[1], ε[1] - ε[2]]
    long_roots = vcat(long_roots, [-r for r in long_roots])
    roots = vcat(short_roots, long_roots)
    identity2 = [1 0; 0 1]
    identity7 = [Int(i == j) for i in 1:7, j in 1:7]

    subheading("The root system R: short roots ±ε_i, long roots ε_i - ε_j, ε1 + ε2 + ε3 = 0")
    α, β = ε[1], ε[3] - ε[1]
    in_base(r) = let a = r[1] - 2r[2], b = -r[2]
        a * α + b * β == r && (min(a, b) >= 0 || max(a, b) <= 0)
    end
    claim("α = ε1 and β = ε3 - ε1 form a base of R: every root is mα + nβ with m, n ≥ 0 or m, n ≤ 0", all(in_base, roots))
    check("|det(α, β)|: they span X^* = Zε1 + Zε2", 1, abs(α[1] * β[2] - α[2] * β[1]))
    bil(x, y) = 2x[1] * y[1] - x[1] * y[2] - x[2] * y[1] + 2x[2] * y[2]   # W-invariant: (ε_i, ε_i) = 2, (ε1, ε2) = -1
    cartan = [2bil(a, b) // bil(b, b) for a in (α, β), b in (α, β)]
    check("Cartan matrix of (α, β) and its determinant (1: the root lattice is the weight lattice)", ([2 -1; -3 2], 1),
          (Int.(cartan), Int(cartan[1, 1] * cartan[2, 2] - cartan[1, 2] * cartan[2, 1])))
    reflect(γ) = hcat([x - Int(2bil(x, γ) // bil(γ, γ)) * γ for x in ([1, 0], [0, 1])]...)
    W = s8_generate([reflect(α), reflect(β)], identity2)
    check("order of the Weyl group ⟨s_α, s_β⟩ (the dihedral group D12 in its reflection representation)", 12, length(W))
    claim("it permutes the 12 roots", all(g -> Set(g * r for r in roots) == Set(roots), W))

    subheading("The weights of K^7: e_i has weight ε_i")
    claim("the weights of K^7 (the six short roots and 0) have multiplicity one, so T forces x1, ..., x7", allunique(ε))

    subheading("Proposition prop:trilinear")
    triples = [(i, j, k) for i in 1:7 for j in i+1:7 for k in j+1:7 if ε[i] + ε[j] + ε[k] == [0, 0]]
    check("the T-invariant basis vectors of ∧3 K^7", [(1, 2, 3), (1, 4, 7), (2, 5, 7), (3, 6, 7), (4, 5, 6)], triples)
    characters = [Int(k in t) for t in [(1, 2, 3), (4, 5, 6), (1, 4, 7), (2, 5, 7), (3, 6, 7)], k in 1:7]
    check("the characters s ↦ s_i s_j s_k scaling the c_ijk: the stabilizer in D of a T-invariant form with k nonzero c_ijk " *
          "has dimension 7 - k, for every k = 1, ..., 5 and every choice of the k (2 only for k = 5)", [[6], [5], [4], [3], [2]],
          [unique(7 - rank(matrix(QQ, characters[S, :])) for S in Combinatorics.combinations(1:5, k)) for k in 1:5])
    check("exponent vector of r(c) = c147 c257 c367 / (c123 c456): s multiplies r(c) by s_7^3", [0, 0, 0, 0, 0, 0, 3],
          characters[3, :] + characters[4, :] + characters[5, :] - characters[1, :] - characters[2, :])
    check("elementary divisors of the characters: the stabilizer of Φ in D is a 2-dimensional torus times μ_3",
          ZZ.([1, 1, 1, 1, 3]), elementary_divisors(matrix(ZZ, characters)))

    subheading("Proof of Theorem thm:homogeneous(a): the contraction ∧2 K^7 → (K^7)^∨, its kernel E and their weights")
    forms = phi_linear_forms()
    claim("the linear forms have coefficients ±1 and disjoint supports (so the contraction is onto over ZZ)",
          all(c -> c in (0, 1, -1), reduce(vcat, forms)) && all(k -> count(f -> !iszero(f[k]), forms) <= 1, 1:21))
    check("dim E = 21 - 7", 14, 21 - rank_of(forms))
    multiplicity(w) = count(p -> weight(p...) == w, PAIRS)
    check("weights of the p_ij: multiplicity of each long root, of each short root, of 0",
          [1, 2, 3], [only(unique(multiplicity.(long_roots))), only(unique(multiplicity.(short_roots))), multiplicity([0, 0])])
    check("the p_ij of weight ε1, and of weight 0", [[(1, 7), (5, 6)], [(1, 4), (2, 5), (3, 6)]],
          [[p for p in PAIRS if weight(p...) == ε[1]], [p for p in PAIRS if weight(p...) == [0, 0]]])
    hexagon = Set([(1, 5), (1, 6), (2, 4), (2, 6), (3, 4), (3, 5)])
    claim("the long roots are the weights of the hexagon edges", Set(p for p in PAIRS if weight(p...) in long_roots) == hexagon)
    claim("L_i is homogeneous of weight -ε_i (the weights of (K^7)^∨)",
          all(i -> all(k -> iszero(forms[i][k]) || weight(PAIRS[k]...) == -ε[i], 1:21), 1:7))
    multiplicity_E(w) = multiplicity(w) - count(i -> -ε[i] == w, 1:7)
    check("weights of E: multiplicity of each long root, of each short root, of 0 (the zero weight plane E_0)", [1, 1, 2],
          [only(unique(multiplicity_E.(long_roots))), only(unique(multiplicity_E.(short_roots))), multiplicity_E([0, 0])])
    check("L_7 = p14 + p25 + p36: E_0 = {c1 e14 + c2 e25 + c3 e36 : c1 + c2 + c3 = 0}, and p36 = -(p14 + p25) on G",
          [(1, 4) => 1, (2, 5) => 1, (3, 6) => 1], [p => phi(7, p...) for p in PAIRS if phi(7, p...) != 0])
    claim("the 21 weights e_i + e_j of the p_ij under the diagonal torus D are distinct",
          allunique([[Int(k in p) for k in 1:7] for p in PAIRS]))
    check("the p_ij whose weight is a root (forced by T on E)", 18, count(p -> weight(p...) != [0, 0], PAIRS))
    form_support(f) = Set(PAIRS[k] for k in 1:21 if !iszero(f[k]))
    claim("the two p_ij of each short root are the support of one linear form, so they agree up to sign on L",
          all(w -> Set(p for p in PAIRS if weight(p...) == w) in form_support.(forms), short_roots))

    subheading("Remark after the proof of thm:homogeneous(a): the highest weights of K^7 and ∧2 K^7 for the base α, β")
    in_αβ(r) = [r[1] - 2r[2], -r[2]]                       # r = mα + nβ
    highest(weights) = only(filter(λ -> all(μ -> all(>=(0), in_αβ(λ - μ)), weights), unique(weights)))
    λ1, λ2 = highest(ε), highest([weight(p...) for p in PAIRS])
    check("(m, n) of the highest weight mα + nβ of K^7, the e_i of that weight; the same for ∧2 K^7 and the e_i ∧ e_j " *
          "(2α + β = ε5 and 3α + 2β = ε3 + ε5, with weight lines K e5 and K e3 ∧ e5)", ([2, 1], [5], [3, 2], [(3, 5)]),
          (in_αβ(λ1), findall(==(λ1), ε), in_αβ(λ2), [p for p in PAIRS if weight(p...) == λ2]))

    subheading("Proof of Theorem thm:homogeneous(b): N/T = D12 and its lifts (homogeneous_spaces/tropicalizing_reductive_groups_tits.jl)")
    cited("the Weyl group of T in G2 is N/T ≅ D12 [Aschbacher, (2.11) and (3.4)]")
    m = run_in_module(study_path("g2", "homogeneous_spaces", "tropicalizing_reductive_groups_tits.jl"); name=:TitsLifts)
    R, S, Dg, N48 = latest(m, :R), latest(m, :S), latest(m, :D), latest(m, :group)
    check("lifts in G2 of the rotation and of the reflection; signed diagonal elements; order of N(T)(ZZ)", [4, 4, 4, 48],
          [length(R), length(S), length(Dg), length(N48)])
    n_ρ = call(m, :signed_permutation_matrix, latest(m, :rotation), [1, 1, 1, 1, 1, 1, -1])
    n_τ = call(m, :signed_permutation_matrix, latest(m, :reflection), [-1, -1, -1, -1, -1, -1, 1])
    claim("n_ρ (e_i ↦ e_ρ(i), e7 ↦ -e7) and n_τ (e_i ↦ -e_τ(i), e7 ↦ e7) fix Φ and have determinant 1", n_ρ in R && n_τ in S)
    check("the signed diagonal elements of G2: diag(a, b, ab, a, b, ab, 1), a, b = ±1",
          sort([[a, b, a * b, a, b, a * b, 1] for a in (1, -1) for b in (1, -1)]), sort([[g[k, k] for k in 1:7] for g in Dg]))
    perm_of(g) = [findfirst(!iszero, g[:, i]) for i in 1:7]
    H = s8_generate([n_ρ, n_τ], identity7)
    D12 = Set(perm_of.(collect(N48)))
    check("⟨n_ρ, n_τ⟩: its order and the permutations it lifts; permutations of the 48 elements of N(T)(ZZ)", [12, 12, 12],
          [length(H), length(Set(perm_of.(collect(H)))), length(D12)])
    claim("these 12 permutations are the group D12 of Section 2 (the census symmetry group of trop(G))",
          D12 == Set(load_symmetry_artifacts(g2("grassmannian", "05_symmetry")).permutations))
    claim("relabeling the x_i by w in D12 permutes the five e_ijk of weight zero (proof of thm:homogeneous(a))",
          all(w -> Set(Set(w[i] for i in t) for t in triples) == Set(Set(t) for t in triples), D12))
    on_lattice(w) = hcat(ε[w[1]], ε[w[2]])                 # the linear map ε1 ↦ ε_w(1), ε2 ↦ ε_w(2)
    claim("each w in D12 acts on X^* by ε_i ↦ ε_w(i), linearly, and these 12 maps are the Weyl group W",
          all(w -> all(i -> on_lattice(w) * ε[i] == ε[w[i]], 1:7), D12) && Set(on_lattice.(collect(D12))) == W)
    signs_of(g) = join(g[perm_of(g)[i], i] > 0 ? "+" : "-" for i in 1:7)
    order_of(g) = findfirst(k -> g^k == identity7, 1:24)
    for (name, lifts) in (("ρ", R), ("τ", S))
        info("lifts of $name (signs s_i in e_i ↦ s_i e_$(name)(i)) and their orders: " *
             join(["$(signs_of(g)) $(order_of(g))" for g in sort(lifts; by=signs_of)], ", "))
    end
    split_pairs = [(a, b) for a in R for b in S if a^6 == identity7 && b^2 == identity7 && (b * a)^2 == identity7]
    info("pairs (lift of ρ, lift of τ) with a^6 = b^2 = (ba)^2 = 1, each generating a copy of D12: $(length(split_pairs)); " *
         "the paper's (n_ρ, n_τ) is one of them: $((n_ρ, n_τ) in split_pairs)")
    root_names = Dict(ε[1] => "ε1", ε[2] => "ε2", ε[3] => "ε3", ε[1] - ε[2] => "ε1-ε2", ε[2] - ε[3] => "ε2-ε3", ε[3] - ε[1] => "ε3-ε1")
    function lattice_type(A)
        if A[1, 1] * A[2, 2] - A[1, 2] * A[2, 1] == 1
            return (1, findfirst(k -> A^k == identity2, 1:6)), "rotation of order $(findfirst(k -> A^k == identity2, 1:6))"
        end
        γ = only(r for r in keys(root_names) if A * r == -r)
        return (2, length(root_names[γ])), "reflection s_$(root_names[γ]) in a $(length(root_names[γ]) == 2 ? "short" : "long") root"
    end
    info("D12 = N/T: each permutation of [7], its matrix on X^* in the basis ε1, ε2, and its type")
    for w in sort(collect(D12); by=w -> (first(lattice_type(on_lattice(w))), w))
        info("  " * rpad(s8_cycles(w), 18) * rpad(string(on_lattice(w)), 14) * last(lattice_type(on_lattice(w))))
    end

    subheading("The signs matter: the permutation matrix of τ does not preserve L")
    ρ, τ = latest(m, :rotation), latest(m, :reflection)
    signed_lifts = [(ρ, [1, 1, 1, 1, 1, 1, -1]), (τ, [-1, -1, -1, -1, -1, -1, 1])]
    # e_i ↦ signs[i] e_perm[i] on a coefficient vector over the 21 p_ij (signed permutation matrices are orthogonal)
    function act21(f, perm, signs)
        out = [QQ(0) for _ in 1:21]
        for (k, (i, j)) in enumerate(PAIRS)
            out[PAIR_INDEX[minmax(perm[i], perm[j])]] += f[k] * signs[i] * signs[j] * (perm[i] < perm[j] ? 1 : -1)
        end
        return out
    end
    unsigned = act21(forms[1], τ, fill(1, 7))
    check("the permutation matrix of τ maps p23 + p47 to p47 - p23 (coefficients)", [(2, 3) => QQ(-1), (4, 7) => QQ(1)],
          [PAIRS[k] => unsigned[k] for k in 1:21 if !iszero(unsigned[k])])
    claim("which is not in the span of the linear forms (the unsigned τ does not preserve L)", rank_of(vcat(forms, [unsigned])) == 8)

    subheading("The hypotheses of Lemma lem:tropical-group: the coordinates x_i, p_ij have weights ε_i, ε_i + ε_j")
    weights28 = vcat(ε, [weight(p...) for p in PAIRS])        # x1..x7, then the p_ij
    homogeneous(f, w) = allequal(sum(e[k] * w[k] for k in eachindex(e)) for e in AbstractAlgebra.exponent_vectors(f))
    check("generators of the ideals of Q, G, F that are homogeneous for deg x_i = ε_i, deg p_ij = ε_i + ε_j (T-stable)", [1, 42, 78],
          [count(f -> homogeneous(f, w), gens(load(g2(t, "00_ideal.mrdi"))))
           for (t, w) in (("pointspace", ε), ("grassmannian", weights28[8:28]), ("flag", weights28))])

    subheading("The translations by trop(T) are the star trees (a, -a, 0) and span the lineality spaces")
    star(v) = [v[i] + v[j] for (i, j) in PAIRS]
    us = [[1, -1, 0, -1, 1, 0, 0], [0, 1, -1, 0, -1, 1, 0]]        # u = (a, -a, 0): the first two rows of eq:lineality
    indicator(n, range) = [QQ(k in range ? 1 : 0) for k in 1:n]
    grass = ([QQ.(star(v)) for v in us], [indicator(21, 1:21)])
    flagt = ([QQ.(vcat(v, star(v))) for v in us], [indicator(28, 1:7), indicator(28, 8:28)])
    union24 = ([vcat(t, [QQ(0), QQ(0), QQ(0)]) for t in first(grass)], [indicator(24, 1:24)])
    for (target, (translations, all_ones)) in (("grassmannian", grass), ("grassmannian_gf2", grass), ("flag", flagt),
                                              ("flag_gf2", flagt), ("slong", grass), ("short_long", union24))
        _, lin = fan_rays(fan(target))
        claim("$target: the translations (⟨χ_s, u⟩)_s and the all-ones vectors span the lineality space",
              rank_of(lin) == rank_of(vcat(translations, all_ones)) == rank_of(vcat(lin, translations, all_ones)),
              "dimension $(rank_of(lin))")
    end

    subheading("N preserves Gr(2,7) and L and permutes the 78 polynomials of the flag Dressian, over every field")
    claim("n_ρ and n_τ map the span of the seven linear forms to itself (N preserves L)",
          all(x -> rank_of(vcat(forms, [act21(f, x[1], x[2]) for f in forms])) == 7, signed_lifts))
    J = load(g2("flag", "00_ideal.mrdi"))
    SJ, GJ = base_ring(J), gens(J)
    # x_i ↦ s_i x_perm(i), p_ij ↦ s_i s_j p_perm(i)perm(j); variables x1..x7, then the p_ij in the order of PAIRS
    substitution(perm, signs) = vcat([signs[i] * SJ[perm[i]] for i in 1:7],
        [signs[i] * signs[j] * (perm[i] < perm[j] ? 1 : -1) * SJ[7 + PAIR_INDEX[minmax(perm[i], perm[j])]] for (i, j) in PAIRS])
    permuted(perm, signs) = count(f -> (img = evaluate(f, substitution(perm, signs)); img in GJ || -img in GJ), GJ)
    check("generators of the flag ideal sent to ± a generator by n_ρ and by n_τ (they permute the 78 tropical polynomials)",
          [78, 78], [permuted(perm, signs) for (perm, signs) in signed_lifts])
    info("without signs, the permutation matrix of τ sends $(permuted(τ, fill(1, 7))) of the 78 to ± a generator")
    # trop_{L_long}(G) and the union come with their subsection below
    census_groups = [Set(load_symmetry_artifacts(joinpath(TARGET_DIRECTORIES[t], "05_symmetry")).permutations)
                     for t in ("dressian", "flag_dressian", "grassmannian", "flag", "grassmannian_gf2", "flag_gf2")]
    check("census symmetry groups of the two Dressians, trop(G), trop(F) over QQ and GF(2): their orders, and each is " *
          "the D12 lifted by N(T)(ZZ)", (fill(12, 6), true), (length.(census_groups), all(==(D12), census_groups)))

    subheading("The zero weight space E_0: E_0^∨ ≅ X^* ⊗ K, and E → Lie(G2)")
    claim("p_{i,i+3} ↦ ε_i is D12-equivariant: every element of N(T)(ZZ) maps e_i ∧ e_{i+3} to +e_w(i) ∧ e_w(i+3)",
          all(g -> all(i -> abs(perm_of(g)[i] - perm_of(g)[i + 3]) == 3 && g[perm_of(g)[i], i] * g[perm_of(g)[i + 3], i + 3] == 1,
                       1:3), N48))
    lie_dimension, A = stabilizer_dimension(QQ)            # A vec(X) = 0 for the derivations X of Φ, X[m, i] at 7(i - 1) + m
    Ajl = Matrix{QQFieldElem}(A)
    # u ∧ v ↦ b(u, .) v - b(v, .) u, as a 7 x 7 matrix, for an element of ∧2 K^7 given by its 21 coefficients
    to_matrix(c) = [sum(c[k] * (POLAR[i, n] * Int(r == j) - POLAR[j, n] * Int(r == i)) for (k, (i, j)) in enumerate(PAIRS))
                    for r in 1:7, n in 1:7]
    _, Ebasis = nullspace(matrix(QQ, reduce(vcat, permutedims.(forms))))
    images = [to_matrix([Ebasis[k, c] for k in 1:21]) for c in 1:ncols(Ebasis)]
    in_lie(X) = all(iszero, Ajl * vec(X))
    claim("over QQ, u ∧ v ↦ b(u, .) v - b(v, .) u maps E into Lie(G2) = Der(Φ), onto it (rank 14 = dim Lie(G2))",
          all(in_lie, images) && rank_of([vec(X) for X in images]) == lie_dimension == 14)
    e0 = [indicator(21, [PAIR_INDEX[(1, 4)]]) - indicator(21, [PAIR_INDEX[(2, 5)]]),
          indicator(21, [PAIR_INDEX[(2, 5)]]) - indicator(21, [PAIR_INDEX[(3, 6)]])]
    diagonal_positions = [7 * (i - 1) + i for i in 1:7]
    cartan_dimension = 7 - rank(matrix(QQ, Ajl[:, diagonal_positions]))
    claim("it maps E_0 onto the Cartan subalgebra h (the diagonal elements of Lie(G2))",
          all(X -> in_lie(X) && all(iszero(X[r, n]) for r in 1:7, n in 1:7 if r != n), to_matrix.(e0)) &&
          rank_of([vec(X) for X in to_matrix.(e0)]) == cartan_dimension == 2, "dim h = $cartan_dimension")
    # main.tex: "If char(K) ≠ 3, then E is the adjoint representation g and E_0 is the Cartan subalgebra h", and in
    # characteristic 3 "we leave open whether E ≅ g". Over GF(p), E is the kernel of the contraction mod p and
    # Lie(G2) = Der(Φ) ∩ sl_7 (the stabilizer is smooth, Section 1): in char 3 the identity is a derivation (3Φ = 0).
    for p in (2, 3)
        K = GF(p)
        lie_p, A_p = stabilizer_dimension(K; trace_zero=true)
        _, E_p = nullspace(matrix(K, [phi(i, j, k) for i in 1:7, (j, k) in PAIRS]))
        on_rows(Xs) = matrix(K, reduce(vcat, permutedims.(vec.(Xs))))
        M_p = on_rows([to_matrix([E_p[k, c] for k in 1:21]) for c in 1:ncols(E_p)])
        e0_p = [to_matrix([K(numerator(x)) for x in v]) for v in e0]
        h_p = 7 - rank(matrix(K, Matrix(A_p)[:, diagonal_positions]))
        claim("over GF($p), the same map sends E onto Lie(G2) = Der(Φ) ∩ sl_7 (rank 14) and E_0 onto its diagonal part h" *
              (p == 3 ? " (main.tex leaves characteristic 3 open: this map is a G2-equivariant isomorphism E → g there too)" :
                        " (main.tex: \"If char(K) ≠ 3\")"),
              ncols(E_p) == 14 && iszero(A_p * transpose(M_p)) && rank(M_p) == lie_p == 14 &&
              iszero(A_p * transpose(on_rows(e0_p))) && all(X -> all(iszero(X[r, n]) for r in 1:7, n in 1:7 if r != n), e0_p) &&
              rank(on_rows(e0_p)) == h_p == 2,
              "dim Der(Φ) = $(first(stabilizer_dimension(K))), dim Der(Φ) ∩ sl_7 = $lie_p, dim h = $h_p")
    end
    cited("a vector of weight θ generates a subrepresentation of E onto the simple module of highest weight θ [Jantzen, " *
          "II.2.13], of dimension 14 [Hogeweij, I.2.7a]; in characteristic 3 the short roots generate a 7-dimensional ideal " *
          "of g [Hogeweij, I, Table 1]")

    subheading("Forgetting p36: the basis L = {QQε1, QQε2} of E_0^∨ (homogeneous_spaces/tropicalizing_reductive_groups.jl)")
    F = fan("grassmannian")
    _, lineality = fan_rays(F)
    e36 = indicator(21, [PAIR_INDEX[(3, 6)]])
    cones = collect(maximal_cones(F))
    spans = [vcat([QQ.(collect(r)) for r in rays_modulo_lineality(C).rays_modulo_lineality], lineality) for C in cones]
    contracted = [rank_of(vcat(sp, [e36])) == rank_of(sp) for sp in spans]
    check("maximal cells of trop(G); kept, and contracted (their span contains e36)", [248, 227, 21],
          [length(cones), count(!, contracted), count(contracted)])
    keep = [k for k in 1:21 if k != PAIR_INDEX[(3, 6)]]
    function image_span(sp)
        rk, Rm = rref(matrix(QQ, reduce(vcat, permutedims.([v[keep] for v in sp]))))
        return Matrix{QQFieldElem}(Rm[1:rk, :])
    end
    distinct = length(unique(image_span(sp) for (sp, c) in zip(spans, contracted) if !c))
    txt = readlines(study_path("g2", "homogeneous_spaces", "tropicalizing_reductive_groups.txt"))
    stored_distinct = parse(Int, match(r"distinct spans (\d+)", only(l for l in txt if startswith(l, "non-vertical cells"))).captures[1])
    convex = strip(only(l for l in txt if startswith(l, "pairs with convex union")))
    claim("the 227 kept cells have $distinct distinct images: $(227 - distinct) pairs merge after forgetting p36, " *
          "so the coarsest structure of trop_L(G) has $distinct maximal cells (the paper does not say)",
          distinct == stored_distinct, "tropicalizing_reductive_groups.txt: $stored_distinct distinct spans, $convex")
    stored("initial ideals in the weight basis on the kept cells (tropicalizing_reductive_groups.jl)",
           strip(only(l for l in txt if startswith(l, "computed "))))
    info("from tropicalizing_reductive_groups.txt: " * strip(only(l for l in txt if startswith(l, "cells containing e_36"))))
    info("the 248 cells of trop(G) by (d14, d25, d36) and toric status, there:")
    foreach(l -> info("  " * l), filter(l -> occursin(r"^d(14|36)", l) && !occursin("weight-basis", l), txt))
    foreach(l -> info(l), filter(l -> startswith(l, "toric cells in the weight basis") ||
                                      startswith(l, "distinct toric initial ideals"), txt))

    subheading("No basis of E_0^∨ is D12-stable: the orbits of lines in X^*_QQ and the two tripods")
    primitive = [[a, b] for a in -6:6 for b in -6:6 if gcd(a, b) == 1]
    line_orbit(v) = unique(sort([g * v, -(g * v)]) for g in W)
    claim("no D12-stable basis {QQv, QQv'} of E_0^∨: every orbit of lines has more than 2 elements (primitive v in [-6, 6]^2)",
          all(v -> length(line_orbit(v)) > 2, primitive))
    check("sizes of the D12-orbits of lines QQv in X^*_QQ (primitive v in [-6, 6]^2)", [3, 6],
          sort(unique(length.(line_orbit.(primitive)))))
    tripod(vs) = Set(sort([v, -v]) for v in vs)
    claim("the orbit of QQε1 is the short tripod {QQε1, QQε2, QQε3}, the orbit of QQ(ε2 - ε3) the long tripod " *
          "{QQ(ε2 - ε3), QQ(ε3 - ε1), QQ(ε1 - ε2)}",
          Set(line_orbit(ε[1])) == tripod(ε[1:3]) &&
          Set(line_orbit(ε[2] - ε[3])) == tripod([ε[2] - ε[3], ε[3] - ε[1], ε[1] - ε[2]]))
    info("a generic orbit, of QQ(3ε1 + ε2), in the basis ε1, ε2: " *
         join(["QQ" * string(Tuple(last(l))) for l in sort(line_orbit([3, 1]); by=last)], ", "))

    subheading("The long tripod and the union of both tripods (run_census_slong.jl)")
    Ju = load(g2("grassmannian_Slong", "short_long", "00_ideal.mrdi"))
    Su = base_ring(Ju)
    P(i, j) = Su[PAIR_INDEX[(i, j)]]
    linear_generators = [f for f in gens(Ju) if total_degree(f) == 1]
    claim("the coordinates 22-24 of the union are u = p25 - p36, v = p36 - p14, w = p14 - p25: the long tripod's " *
          "\"p_{14}-p_{25},p_{14}-p_{36},p_{25}-p_{36}\" up to sign (generators of short_long/00_ideal.mrdi)",
          all(f -> f in linear_generators || -f in linear_generators,
              [Su[22] - P(2, 5) + P(3, 6), Su[23] - P(3, 6) + P(1, 4), Su[24] - P(1, 4) + P(2, 5)]))
    gs, s, u = summary("grassmannian"), summary("slong"), summary("short_long")
    check("f-vectors of trop_{L_long}(G) and of trop(G)", ([42, 211, 275], [51, 241, 248]),
          (s["complex"]["f_vector"], gs["complex"]["f_vector"]))
    check("the union of both tripods: rays and maximal cells", [57, 383], [u["complex"]["f_vector"][1], u["complex"]["maximal_cells"]])
    projections = TOML.parsefile(g2("grassmannian_Slong", "07_projections.toml"))
    covered(k) = sum(o["orbit_size"] for o in projections[k]["orbits"] if o["lifted_bijectively"] || o["cells_over_each"] > 1)
    stored("the union projects onto both: maximal cells of trop(G) and of trop_{L_long}(G) that are the image of one cell " *
           "of the union, or covered by the cells over them, by run_census_slong.jl (07_projections.toml)",
           [covered("short"), covered("long")]; paper=[248, 275])
    stored("the union in 07_projections.toml: rays and maximal cells", [projections["both"]["rays"], projections["both"]["maximal_cells"]];
           paper=[57, 383])
    for k in ("short", "long")
        pr = projections[k]
        cut = [o for o in pr["orbits"] if !o["lifted_bijectively"]]
        info("over trop_{L_$k}(G): $(pr["cells_lifted_bijectively"]) cells lift to one cell of the union, " *
             "$(sum(o["orbit_size"] for o in cut)) cells ($(length(cut)) orbit$(length(cut) == 1 ? "" : "s")) are cut into " *
             "$(join(unique(o["cells_over_each"] for o in cut), "/")), $(pr["vertical_source_cells"]) cells of the union are vertical")
    end
    check("the Weyl group acts on trop_{L_long}(G) and on the union: orders of their census symmetry groups", [12, 12],
          [s["complex"]["group_order"], u["complex"]["group_order"]])
    types(x) = join(["$(t["cells"]) $(t["type"])s" for t in x["maximal_cell_types"]], ", ")
    toric(x) = haskey(x, "degenerations") ? "$(x["degenerations"]["toric_cells"]) in $(x["degenerations"]["toric_orbits"]) orbits" : "-"
    info(rpad("", 22) * rpad("trop(G)", 26) * rpad("trop_{L_long}(G)", 26) * "union")
    for (label, f) in (("f-vector", x -> show_value(x["complex"]["f_vector"])),
                       ("orbit f-vector", x -> show_value(x["complex"]["orbit_f_vector"])),
                       ("maximal cells", types), ("reduced homology", x -> x["reduced_homology"]["description"]),
                       ("toric degenerations", toric))
        info(rpad(label, 22) * rpad(f(gs), 26) * rpad(f(s), 26) * f(u))
    end
    status(r, side) = r["$(side)_dimension"] != "3" ? "vertical" : r["$(side)_equal"] == "true" ? "a cell" : "inside a cell"
    classes = Dict{Tuple{String,String},Vector{Int}}()
    orbit_rows = rows(g2("grassmannian_Slong", "07_projections.csv"))
    for r in orbit_rows
        classes[(status(r, "short"), status(r, "long"))] = get(classes, (status(r, "short"), status(r, "long")), [0, 0]) +
                                                           [1, parse(Int, r["size"])]
    end
    info("the $(length(orbit_rows)) orbits of maximal cells of the union by their images (07_projections.csv):")
    for ((short, long), (orbits, cells)) in sort(collect(classes))
        info("  in trop(G) $(rpad(short, 14)) in trop_{L_long}(G) $(rpad(long, 14)) $orbits orbits, $cells cells")
    end
    toric_cells(side) = sum(parse(Int, r["size"]) for r in orbit_rows if r["$(side)_toric"] == "true"; init=0)
    info("cells of the union with a toric image in trop(G): $(toric_cells("short")), in trop_{L_long}(G): $(toric_cells("long")), " *
         "in both: $(sum(parse(Int, r["size"]) for r in orbit_rows if r["short_toric"] == r["long_toric"] == "true"; init=0))")

    subheading("The long roots are not Plücker coordinates (homogeneous_spaces/long_root_check.jl)")
    m = run_in_module(study_path("g2", "homogeneous_spaces", "long_root_check.jl"); name=:LongRoots)
    claim("the 4x4 Pfaffians: unit ideal for p14 - p25, the point a = 0 for p14",
          is_one(latest(m, :long_root)) && latest(m, :short_root) == ideal(latest(m, :R), latest(m, :a)))

    subheading("The coordinates the union adds (short_long/03_normalized_coarsest_fan.mrdi, min convention: d = -x)")
    # u, v, w are the coordinates 22-24 of the union, x_u = val(p25 - p36) etc.: x_u = min(x25, x36) unless x25 = x36
    differences = [(PAIR_INDEX[(2, 5)], PAIR_INDEX[(3, 6)], 22), (PAIR_INDEX[(3, 6)], PAIR_INDEX[(1, 4)], 23),
                   (PAIR_INDEX[(1, 4)], PAIR_INDEX[(2, 5)], 24)]
    valuation_rule(x) = all(((a, b, c),) -> x[a] != x[b] ? x[c] == min(x[a], x[b]) : x[c] >= x[a], differences)
    rays_u, _ = fan_rays(fan("short_long"))
    barycentres = [sum(QQ.(collect(r)) for r in rays_modulo_lineality(C).rays_modulo_lineality) for C in maximal_cones(fan("short_long"))]
    strict = count(x -> any(((a, b, c),) -> x[a] == x[b] && x[c] > x[a], differences), barycentres)
    claim("\"The union adds -val(p_{i,i+3}-p_{j,j+3}), which is max(d_{i,i+3},d_{j,j+3}) unless d_{i,i+3}=d_{j,j+3}\": " *
          "at every ray and every cell barycentre of the union",
          all(valuation_rule, rays_u) && all(valuation_rule, barycentres),
          "$(length(rays_u)) rays, $(length(barycentres)) cells; in $strict cells it is < d_{i,i+3} = d_{j,j+3} for some pair")

    subheading("Characteristics 3 and 2")
    check("the long roots span a sublattice of index 3 of X^*", 3, abs(long_roots[1][1] * long_roots[2][2] - long_roots[1][2] * long_roots[2][1]))
    claim("modulo 2X^*, every primitive vector is congruent to some ε_i", Set(mod.(v, 2) for v in primitive) == Set(mod.(ε[i], 2) for i in 1:3))
end
